CREATE FUNCTION [dbo].[TAI_FN_ItemPolPre]         (@ItemCode       nVarChar(20)    --         ,@WhsCode        nVarChar(8)        ,@PrecioCtoBase  Decimal(19,6)   -- Precio de Costo Base Expresado en Moneda Local        ,@Fecha          DateTime        ,@Retorno        Char(2) = 'MM' )          /* indica tipo de retorno:             MM = % margen mínimo             CO = % comisión            MV = Precio mínimo de venta            DM = % dscto. máximo            CI = Costo Item         */  RETURNS Decimal(19,6) AS  /* Descripción de Rutina  */  BEGIN     DECLARE @MargenItem Decimal(19,6), @ComisItem   Decimal(19,6), @BajoCosto Decimal(19,6)     DECLARE @MonedaPV   nChar(3)     DECLARE @PrecioVta  Decimal(19,6), @PrecioCto   Decimal(19,6)     DECLARE @PVMinItem  Decimal(19,6), @PVentaItem  Decimal(19,6), @PVBajoCosto Decimal(19,6)     DECLARE @CostoItem  Decimal(19,6)     DECLARE @Resultado  Decimal(19,6)     --     SELECT             @MargenItem = CASE ISNULL(ITW.U_VK_PrctMargenMin,0)                       WHEN 0 THEN                 CASE ISNULL(PPS.U_PrctMargenMin,0)                   WHEN 0 THEN                 CASE ISNULL(ITM.U_VK_PrctMargenMin,0)                WHEN 0 THEN PPL.U_PrctMargenMin             ELSE ITM.U_VK_PrctMargenMin             END             ELSE PPS.U_PrctMargenMin          END           ELSE ITW.U_VK_PrctMargenMin        END     , @BajoCosto = CASE ISNULL(PPL.U_PrctBajoMargen, 0)         WHEN 0 THEN 0         ELSE PPL.U_PrctBajoMargen         END     ,@ComisItem  = CASE ISNULL(PPS.U_PrctComisVtas,0)                       WHEN 0 THEN                            CASE ISNULL(ITM.U_VK_PrctComisVtas,0)                               WHEN 0 THEN ISNULL(PPL.U_PrctComisVtas,0)                               ELSE ITM.U_VK_PrctComisVtas                            END                       ELSE PPS.U_PrctComisVtas                    END           ,@MonedaPV   = ISNULL(IPV.Currency,'CLP')           ,@CostoItem  = @PrecioCtoBase           ,@PVentaItem = IPV.Price * ISNULL(TCV.Rate,1)       FROM      OITM            ITM            JOIN OITW            ITW  ON ITM.ItemCode     = ITW.ItemCode            JOIN ITM1            IPV  ON ITM.ItemCode     = IPV.ItemCode                                     AND IPV.PriceList    = 1            JOIN ITM1            IPC  ON ITM.ItemCode     = IPC.ItemCode                                     AND IPC.PriceList    = 2            JOIN OWHS            WHS  ON ITW.WhsCode      = WHS.WhsCode       LEFT JOIN ORTT            TCV  ON IPV.Currency     = TCV.Currency                                     AND TCV.RateDate     = CONVERT(VarChar(8),@Fecha,112)       LEFT JOIN ORTT            TCC  ON IPC.Currency     = TCC.Currency                                     AND TCC.RateDate     = CONVERT(VarChar(8),@Fecha,112)       LEFT JOIN OLCT            LCT  ON WHS.Location     = LCT.Code       LEFT JOIN [@TAI_PPLIN]    PPL  ON ITM.ItmsGrpCod   = PPL.Code       LEFT JOIN [@TAI_PPLINSUC] PPS  ON PPL.Code         = PPS.Code                                     AND PPS.U_SucCodigo  = LCT.Code       WHERE ITM.ItemCode = @ItemCode        AND ITW.WhsCode  = @WhsCode     --     SET @PVMinItem  = ROUND(@CostoItem / (1 - @MargenItem/100),2)     --     SET @PVBajoCosto = ROUND(@CostoItem / (1 - @BajoCosto/100),2)     --     SET @Resultado = CASE @Retorno                         WHEN 'MM' THEN @MargenItem                         WHEN 'CO' THEN @ComisItem                         WHEN 'PM' THEN ROUND(@PVMinItem,2)                         WHEN 'CI' THEN ROUND(@CostoItem,2)                         WHEN 'DM' THEN (case when @PVentaItem=0 then 0 else ROUND(100-(@PVMinItem*100)/@PVentaItem,2) end)--ROUND(100-(@PVMinItem*100)/@PVentaItem,2)                         WHEN 'BC' THEN ROUND(@PVBajoCosto,2)                      END     --     RETURN(@Resultado)  END
CREATE FUNCTION [dbo].[TAI_FN_MONITOR_OV] (@Cliente nvarchar(15),@articulo nvarchar(30), @Estado nvarchar(30), @Fecha1 nvarchar(8), @Fecha2 nvarchar(8), @Vendedor integer)  RETURNS @MonitorCab TABLE   (    DocNum     int NOT NULL   ,CardName   nvarchar(100) NOT NULL   ,TaxDate    DateTime NOT NULL   ,DocDate    DateTime NOT NULL   ,DocDueDate DateTime NOT NULL   ,Estado     nvarchar(30) NOT NULL   ,TipoDoc    nvarchar(2) NOT NULL   ,Tipo       nvarchar(10) NOT NULL    --,OwnerCode  int NOT NULL  )  AS  BEGIN    declare @sw integer  set @sw=1    if @sw=1  begin  --/*==========================*/  --/* INICIO CODIGO OPTIMIZADO */  --/*==========================*/   if @Estado='Autorizados No Creados'   begin    insert into @MonitorCab     select distinct T10.DocNum,T10.CardName,T10.TaxDate,T10.DocDate,T10.DocDueDate,T10.Estado,T10.TipoDoc,T10.Tipo/*,T10.OwnerCode*/ from (     select T0.DocEntry              as DocNum        ,T0.CardName        ,T0.TaxDate        ,T0.DocDate        ,T0.DocDueDate         ,'Autorizados No Creados' as Estado        ,T0.CardCode        ,'OV'                     as TipoDoc        ,'Borrador'               as Tipo         --,T0.OwnerCode       from ODRF T0       --left join ORDR T1 on T1.draftKey=T0.DocEntry      where T0.ObjType     =17      --and T1.draftKey    is null      --and T1.DocDate    >=@Fecha1        and (select count(*) from ORDR where DocDate>=@Fecha1 and draftkey = T0.DocEntry)=0         and T0.U_Estado_Aut='A'        and T0.DocSubType  in('--','IB')        and T0.CardCode    =(case when @Cliente='' then T0.CardCode  else @Cliente  end)         and T0.DocDate     between @Fecha1 and @Fecha2      --and T0.OwnerCode   =(case when @Vendedor=0 then T0.OwnerCode else @Vendedor end)    ) as T10    where T10.CardCode =(case when @Cliente='' then T10.CardCode  else @Cliente  end)       and T10.Estado   =@Estado      and T10.DocDate  between @Fecha1 and @Fecha2          --and T10.OwnerCode=(case when @Vendedor=0 then T10.OwnerCode else @Vendedor end)    order by T10.DocDate desc   end   else if @Estado='Facturados'   begin    insert into @MonitorCab     select distinct T10.DocNum,T10.CardName,T10.TaxDate,T10.DocDate,T10.DocDueDate,T10.Estado,T10.TipoDoc,T10.Tipo/*,T10.OwnerCode*/ from (     select T0.DocNum         ,T0.CardName        ,T0.TaxDate        ,T0.DocDate        ,T0.DocDueDate         ,'Facturados'    as Estado        ,T0.CardCode       --,'FV'            as TipoDoc        ,(case when T0.DocSubType='IB' then 'BV' else 'FV' end) as TipoDoc        ,'Documento'     as Tipo      --,T0.OwnerCode       from OINV T0       where T0.DocSubType in('--','IB')        and T0.CardCode   =(case when @Cliente='' then T0.CardCode  else @Cliente  end)        and T0.DocDate    between @Fecha1 and @Fecha2               --and T10.OwnerCode=(case when @Vendedor=0 then T10.OwnerCode else @Vendedor end)    ) as T10    where T10.CardCode =(case when @Cliente='' then T10.CardCode  else @Cliente  end)       and T10.Estado   =@Estado      and T10.DocDate  between @Fecha1 and @Fecha2          --and T10.OwnerCode=(case when @Vendedor=0 then T10.OwnerCode else @Vendedor end)    order by T10.DocDate desc   end   else   begin    insert into @MonitorCab     select distinct T10.DocNum,T10.CardName,T10.TaxDate,T10.DocDate,T10.DocDueDate,T10.Estado,T10.TipoDoc,T10.Tipo/*,T10.OwnerCode*/ from (     select distinct          T0.DocNum         ,T0.CardName        ,T0.TaxDate        ,T0.DocDate        ,T0.DocDueDate         ,(case when (T0.Canceled = 'Y' or T0.DocStatus = 'C') then 'Pedidos Cancelados' else 'Pendientes de Facturación' end)  as Estado        ,T0.CardCode         ,'OV'        as TipoDoc        ,'Documento' as Tipo      --,T0.OwnerCode       from ORDR T0          inner join RDR1 T1 on T1.DocEntry=T0.DocEntry      where T1.TargetType   = -1        and T0.DocEntry not in (select BaseEntry from DRF1 where BaseEntry=T0.DocEntry and BaseType=T0.ObjType)        and T0.DocSubType   in('--','IB')        and T0.CardCode     =(case when @Cliente='' then T0.CardCode  else @Cliente  end)         and T0.DocDate      between @Fecha1 and @Fecha2      --and T0.OwnerCode    =(case when @Vendedor=0 then T0.OwnerCode else @Vendedor end)     union all     select distinct         T0.DocEntry        ,T0.CardName        ,T0.TaxDate        ,T0.DocDate        ,T0.DocDueDate         ,case         when T0.U_Estado_Aut in ('P', 'R') and T0.ObjType=13 and T1.BaseEntry in (select T2.DocEntry from ORDR T2 inner join RDR1 T3 on T3.DocEntry=T2.DocEntry where T2.CANCELED='Y') then 'Pedidos Cancelados'        when T0.U_Estado_Aut='P'                                                                                                                                                       then 'Pendientes de Autorización'        when T0.U_Estado_Aut='R'                                                                                                                                                       then 'Autorización Rechazada'          end                                              as Estado        ,T0.CardCode        ,(case T0.Objtype when 17 then 'OV'else 'FV' end) as TipoDoc        ,'Borrador'                                       as Tipo      --,T0.OwnerCode       from ODRF T0         inner join DRF1 T1 on T0.docentry=T1.docentry       where T0.ObjType      in (17, 13)      and T0.U_Estado_Aut in ('P', 'R')      and T0.DocSubType   in('--','IB')      and T0.CardCode     =(case when @Cliente='' then T0.CardCode  else @Cliente  end)       and T0.DocDate      between @Fecha1 and @Fecha2       --and T0.OwnerCode    =(case when @Vendedor=0 then T0.OwnerCode else @Vendedor end)    ) as T10    where T10.CardCode =(case when @Cliente='' then T10.CardCode  else @Cliente  end)       and T10.Estado   =@Estado      and T10.DocDate  between @Fecha1 and @Fecha2          --and T10.OwnerCode=(case when @Vendedor=0 then T10.OwnerCode else @Vendedor end)    order by T10.DocDate desc   end  --/*===========================*/  --/* TERMINO CODIGO OPTIMIZADO */  --/*===========================*/  end  else  if @sw=2  begin  ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  -------------------------------------FILTRO POR CLIENTE, ARTICULO, ESTADO Y FECHA -------------------------------------------------  IF @Cliente <> '' AND @articulo <> '' AND @Estado <> '' AND @fecha1 <> '' AND @fecha2 <> ''   insert into @monitorCab    select distinct T200.DocNum, T200.CardName, T200.TaxDate , T200.DocDate, T200.DocDueDate,  T200.Estado, T200.TipoDoc, T200.Tipo  from (      select distinct         T100.DocNum       , T100.CardName      , T100.TaxDate      , T100.DocDate      , T100.DocDueDate       , CASE when (T100.Canceled = 'Y' or T100.DocStatus = 'C') Then 'Pedidos Cancelados'        else 'Pendientes de Facturación' End Estado      , T100.CardCode       , T0.ItemCode      , 'OV' 'TipoDoc'      , 'Documento' 'Tipo'      from ORDR T100       JOIN RDR1 T0 on T0.DocEntry = T100.DocEntry      where T0.TargetType = -1      and T100.DocEntry not in (select BaseEntry from DRF1 where BaseEntry = T100.DocEntry and BaseType = T100.ObjType)      and T100.DocDate >= '20130101'            UNION ALL            select distinct         T100.DocNum       , T100.CardName      , T100.TaxDate      , T100.DocDate      , T100.DocDueDate       , 'Facturados' Estado      , T100.CardCode       , T0.ItemCode      , 'FV' 'TipoDoc'      , 'Documento' 'Tipo'      from OINV T100       JOIN INV1 T0 on T0.DocEntry = T100.DocEntry      where 1 = 1      and T100.DocSubType = '--'      and T100.DocDate >= '20130101'            UNION ALL           select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE when T0.U_Estado_Aut in ('P', 'R') and T0.ObjType = 13 and T1.BaseEntry in (select T0.DocEntry from ORDR T0 JOIN RDR1 T1 on T0.DocEntry = T1.DocEntry where T0.CANCELED = 'Y') Then 'Pedidos Cancelados'          when T0.U_Estado_Aut = 'P' Then 'Pendientes de Autorización'          when T0.U_Estado_Aut = 'R' Then 'Autorización Rechazada' End 'Estado'      , T0.CardCode      , T1.ItemCode      , case T0.Objtype when 17 Then 'OV'            else 'FV' End 'TipoDoc'       , 'Borrador' 'Tipo'      from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (17, 13)      and U_Estado_Aut in ('P', 'R')      and T0.DocDate >= '20160801'            UNION ALL             select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE T0.U_Estado_Aut when 'A' Then 'Autorizados No Creados'       end 'Estado'      , T0.CardCode      , T1.ItemCode      , 'OV' 'TipoDoc'       , 'Borrador' 'Tipo'      from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (17)      and T0.DocDate >= '20160801'      and T0.U_Estado_Aut = 'A'      and (select count(*) from ORDR where draftkey = T0.DocEntry) = 0             UNION ALL            select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE when T0.U_Estado_Aut in ('A', 'N') and (select CANCELED from ORDR where DocEntry = T1.baseentry) = 'N' Then 'Autorizados No Creados'          when (select CANCELED from ORDR where DocEntry = T1.baseentry) = 'Y' Then 'Pedidos Cancelados'       end 'Estado'      , T0.CardCode      , T1.ItemCode      , 'FV' 'TipoDoc'       , 'Borrador' 'Tipo'      from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (13)      and T0.DocDate >= '20160801'      and T0.U_Estado_Aut in ('A', 'N')      and (select count(*) from OINV where draftkey = T0.DocEntry) = 0     ) as T200    WHERE t200.CardCode = @Cliente    AND t200.Estado = @Estado    AND t200.ItemCode = @articulo    AND T200.DocDate BETWEEN @fecha1 AND @fecha2    order by t200.DocDate desc      ------------------------------------------FILTRO POR CLIENTE, ARTICULO Y ESTADO-----------------------------  ELSE IF @articulo <> '' AND @Cliente <> '' AND @Estado <> '' AND @fecha1 = '' AND @fecha2 = ''    insert into @MonitorCab     select distinct T200.DocNum, T200.CardName, T200.TaxDate , T200.DocDate, T200.DocDueDate,  T200.Estado, T200.TipoDoc, T200.Tipo  from (      select distinct         T100.DocNum       , T100.CardName      , T100.TaxDate      , T100.DocDate      , T100.DocDueDate       , CASE when (T100.Canceled = 'Y' or T100.DocStatus = 'C') Then 'Pedidos Cancelados'        else 'Pendientes de Facturación' End Estado      , T100.CardCode       , T0.ItemCode      , 'OV' 'TipoDoc'      , 'Documento' 'Tipo'      from ORDR T100       JOIN RDR1 T0 on T0.DocEntry = T100.DocEntry      where T0.TargetType = -1      and T100.DocEntry not in (select BaseEntry from DRF1 where BaseEntry = T100.DocEntry and BaseType = T100.ObjType)      and T100.DocDate >= '20130101'            UNION ALL            select distinct         T100.DocNum       , T100.CardName      , T100.TaxDate      , T100.DocDate      , T100.DocDueDate       , 'Facturados' Estado      , T100.CardCode       , T0.ItemCode      , 'FV' 'TipoDoc'      , 'Documento' 'Tipo'      from OINV T100       JOIN INV1 T0 on T0.DocEntry = T100.DocEntry      where 1 = 1      and T100.DocSubType = '--'      and T100.DocDate >= '20130101'            UNION ALL           select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE when T0.U_Estado_Aut in ('P', 'R') and T0.ObjType = 13 and T1.BaseEntry in (select T0.DocEntry from ORDR T0 JOIN RDR1 T1 on T0.DocEntry = T1.DocEntry where T0.CANCELED = 'Y') Then 'Pedidos Cancelados'          when T0.U_Estado_Aut = 'P' Then 'Pendientes de Autorización'          when T0.U_Estado_Aut = 'R' Then 'Autorización Rechazada' End 'Estado'      , T0.CardCode      , T1.ItemCode      , case T0.Objtype when 17 Then 'OV'            else 'FV' End 'TipoDoc'       , 'Borrador' 'Tipo'      from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (17, 13)      and U_Estado_Aut in ('P', 'R')      and T0.DocDate >= '20160801'            UNION ALL             select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE T0.U_Estado_Aut when 'A' Then 'Autorizados No Creados'       end 'Estado'      , T0.CardCode      , T1.ItemCode      , 'OV' 'TipoDoc'       , 'Borrador' 'Tipo'      from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (17)      and T0.DocDate >= '20160801'      and T0.U_Estado_Aut = 'A'      and (select count(*) from ORDR where draftkey = T0.DocEntry) = 0             UNION ALL             select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE when T0.U_Estado_Aut in ('A', 'N') and (select CANCELED from ORDR where DocEntry = T1.baseentry) = 'N' Then 'Autorizados No Creados'          when (select CANCELED from ORDR where DocEntry = T1.baseentry) = 'Y' Then 'Pedidos Cancelados'       end 'Estado'      , T0.CardCode      , T1.ItemCode      , 'FV' 'TipoDoc'       , 'Borrador' 'Tipo'      from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (13)      and T0.DocDate >= '20160801'      and T0.U_Estado_Aut in ('A', 'N')      and (select count(*) from OINV where draftkey = T0.DocEntry) = 0     ) as T200    WHERE t200.CardCode = @Cliente    AND t200.Estado = @Estado    AND t200.ItemCode = @articulo    order by DocDate desc        ---------------------------------------------------FILTRO POR CLIENTE, ESTADO Y FECHA------------------------------------  ELSE IF @Cliente <> '' AND @Estado <> '' AND @fecha1 <> '' AND @fecha2 <> '' AND @articulo = ''      insert into @MonitorCab     select distinct T200.DocNum, T200.CardName, T200.TaxDate , T200.DocDate, T200.DocDueDate,  T200.Estado, T200.TipoDoc, T200.Tipo  from (      select distinct         T100.DocNum       , T100.CardName      , T100.TaxDate      , T100.DocDate      , T100.DocDueDate       , CASE when (T100.Canceled = 'Y' or T100.DocStatus = 'C') Then 'Pedidos Cancelados'        else 'Pendientes de Facturación' End Estado      , T100.CardCode       , 'OV' 'TipoDoc'      , 'Documento' 'Tipo'      from ORDR T100       JOIN RDR1 T0 on T0.DocEntry = T100.DocEntry      where T0.TargetType = -1      and T100.DocEntry not in (select BaseEntry from DRF1 where BaseEntry = T100.DocEntry and BaseType = T100.ObjType)      and T100.DocDate >= '20130101'            UNION ALL            select distinct         T100.DocNum       , T100.CardName      , T100.TaxDate      , T100.DocDate      , T100.DocDueDate       , 'Facturados' Estado      , T100.CardCode       , 'FV' 'TipoDoc'      , 'Documento' 'Tipo'      from OINV T100       JOIN INV1 T0 on T0.DocEntry = T100.DocEntry      where 1 = 1      and T100.DocSubType = '--'      and T100.DocDate >= '20130101'            UNION ALL           select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE when T0.U_Estado_Aut in ('P', 'R') and T0.ObjType = 13 and T1.BaseEntry in (select T0.DocEntry from ORDR T0 JOIN RDR1 T1 on T0.DocEntry = T1.DocEntry where T0.CANCELED = 'Y') Then 'Pedidos Cancelados'          when T0.U_Estado_Aut = 'P' Then 'Pendientes de Autorización'          when T0.U_Estado_Aut = 'R' Then 'Autorización Rechazada' End 'Estado'      , T0.CardCode      , case T0.Objtype when 17 Then 'OV'            else 'FV' End 'TipoDoc'       , 'Borrador' 'Tipo'      from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (17, 13)      and U_Estado_Aut in ('P', 'R')      and T0.DocDate >= '20160801'            UNION ALL             select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE when T0.U_Estado_Aut in ('A', 'N') and (select CANCELED from ORDR where DocEntry = T1.baseentry) = 'N' Then 'Autorizados No Creados'          when (select CANCELED from ORDR where DocEntry = T1.baseentry) = 'Y' Then 'Pedidos Cancelados'       end 'Estado'      , T0.CardCode      , 'FV' 'TipoDoc'       , 'Borrador' 'Tipo'      from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (13)      and T0.DocDate >= '20160801'      and T0.U_Estado_Aut in ('A', 'N')      and (select count(*) from OINV where draftkey = T0.DocEntry) = 0             UNION ALL             select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE T0.U_Estado_Aut when 'A' Then 'Autorizados No Creados'       end 'Estado'      , T0.CardCode      , 'OV' 'TipoDoc'       , 'Borrador' 'Tipo'      from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (17)      and T0.DocDate >= '20160801'      and T0.U_Estado_Aut = 'A'      and (select count(*) from ORDR where draftkey = T0.DocEntry) = 0      ) as T200    WHERE T200.CardCode = @Cliente    AND T200.Estado = @Estado    AND T200.DocDate BETWEEN @fecha1 AND @fecha2    order by T200.DocDate desc    -----------------------------------------------------FILTRO POR ARTICULO, ESTADO Y FECHA------------------------------------------  ELSE IF @articulo <> '' AND @Estado <> '' AND @fecha1 <> '' AND @fecha2 <> '' AND @Cliente = ''      insert into @MonitorCab     select distinct T200.DocNum, T200.CardName, T200.TaxDate , T200.DocDate, T200.DocDueDate,  T200.Estado, T200.TipoDoc, T200.Tipo  from (      select distinct         T100.DocNum       , T100.CardName      , T100.TaxDate      , T100.DocDate      , T100.DocDueDate       , CASE when (T100.Canceled = 'Y' or T100.DocStatus = 'C') Then 'Pedidos Cancelados'        else 'Pendientes de Facturación' End Estado      , T0.ItemCode      , 'OV' 'TipoDoc'      , 'Documento' 'Tipo'      from ORDR T100       JOIN RDR1 T0 on T0.DocEntry = T100.DocEntry      where T0.TargetType = -1      and T100.DocEntry not in (select BaseEntry from DRF1 where BaseEntry = T100.DocEntry and BaseType = T100.ObjType)      and T100.DocDate >= '20130101'            UNION ALL            select distinct         T100.DocNum       , T100.CardName      , T100.TaxDate      , T100.DocDate      , T100.DocDueDate       , 'Facturados' Estado      , T0.ItemCode      , 'FV' 'TipoDoc'      , 'Documento' 'Tipo'      from OINV T100       JOIN INV1 T0 on T0.DocEntry = T100.DocEntry      where 1 = 1      and T100.DocSubType = '--'      and T100.DocDate >= '20130101'            UNION ALL           select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE when T0.U_Estado_Aut in ('P', 'R') and T0.ObjType = 13 and T1.BaseEntry in (select T0.DocEntry from ORDR T0 JOIN RDR1 T1 on T0.DocEntry = T1.DocEntry where T0.CANCELED = 'Y') Then 'Pedidos Cancelados'          when T0.U_Estado_Aut = 'P' Then 'Pendientes de Autorización'          when T0.U_Estado_Aut = 'R' Then 'Autorización Rechazada' End 'Estado'      , T1.ItemCode      , case T0.Objtype when 17 Then 'OV'            else 'FV' End 'TipoDoc'      , 'Borrador' 'Tipo'       from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry 