1 = '' AND @fecha2 = ''   insert into @MonitorCab   select distinct T200.DocNum, T200.CardName, T200.TaxDate , T200.DocDate, T200.DocDueDate,  T200.Estado, T200.TipoDoc, T200.Tipo  from (      select distinct         T100.DocNum       , T100.CardName      , T100.TaxDate      , T100.DocDate      , T100.DocDueDate       , CASE when (T100.Canceled = 'Y' or T100.DocStatus = 'C') Then 'Pedidos Cancelados'        else 'Pendientes de Facturación' End Estado      , T100.SlpCode      , 'OV' 'TipoDoc'      , 'Documento' 'Tipo'      from ORDR T100       JOIN RDR1 T0 on T0.DocEntry = T100.DocEntry      where T0.TargetType = -1      and T100.DocEntry not in (select BaseEntry from DRF1 where BaseEntry = T100.DocEntry and BaseType = T100.ObjType)      and T100.DocDate >= '20130101'            UNION ALL            select distinct         T100.DocNum       , T100.CardName      , T100.TaxDate      , T100.DocDate      , T100.DocDueDate       , 'Facturados' Estado      , T100.SlpCode      , 'FV' 'TipoDoc'      , 'Documento' 'Tipo'      from OINV T100       JOIN INV1 T0 on T0.DocEntry = T100.DocEntry      where 1 = 1      and T100.DocSubType = '--'      and T100.DocDate >= '20130101'            UNION ALL           select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE when T0.U_Estado_Aut in ('P', 'R') and T0.ObjType = 13 and T1.BaseEntry in (select T0.DocEntry from ORDR T0 JOIN RDR1 T1 on T0.DocEntry = T1.DocEntry where T0.CANCELED = 'Y') Then 'Pedidos Cancelados'          when T0.U_Estado_Aut = 'P' Then 'Pendientes de Autorización'          when T0.U_Estado_Aut = 'R' Then 'Autorización Rechazada' End 'Estado'      , T0.SlpCode      , case T0.Objtype when 17 Then 'OV'            else 'FV' End 'TipoDoc'       , 'Borrador' 'Tipo'      from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (17, 13)      and U_Estado_Aut in ('P', 'R')      and T0.DocDate >= '20160801'            UNION ALL             select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE T0.U_Estado_Aut when 'A' Then 'Autorizados No Creados'       end 'Estado'      , T0.SlpCode      , 'OV' 'TipoDoc'      , 'Borrador' 'Tipo'       from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (17)      and T0.DocDate >= '20160801'      and T0.U_Estado_Aut = 'A'      and (select count(*) from ORDR where draftkey = T0.DocEntry) = 0             UNION ALL             select distinct T0.DocEntry      , T0.CardName      , T0.TaxDate      , T0.DocDate      , T0.DocDueDate       , CASE when T0.U_Estado_Aut in ('A', 'N') and (select CANCELED from ORDR where DocEntry = T1.baseentry) = 'N' Then 'Autorizados No Creados'          when (select CANCELED from ORDR where DocEntry = T1.baseentry) = 'Y' Then 'Pedidos Cancelados'       end 'Estado'      , T0.SlpCode      , 'FV' 'TipoDoc'       , 'Borrador' 'Tipo'      from ODRF T0      JOIN DRF1 T1 on T0.docentry = T1.docentry      where T0.ObjType in (13)      and T0.DocDate >= '20160801'      and T0.U_Estado_Aut in ('A', 'N')      and (select count(*) from OINV where draftkey = T0.DocEntry) = 0      ) as T200   WHERE t200.Estado = @Estado   order by T200.DocDate desc          ------------------------------------------FILTRO SOLO POR FECHAS-----------------------------------------------------  ELSE IF @fecha1 <> '' and @fecha2 <> '' AND @Cliente = '' AND @articulo = '' AND @Estado = ''    insert into @MonitorCab    select distinct       T100.DocNum     , T100.CardName    , T100.TaxDate    , T100.DocDate    , T100.DocDueDate     , CASE when (T100.Canceled = 'Y' or T100.DocStatus = 'C') Then 'Pedidos Cancelados'        else 'Pendientes de Facturación' End Estado    , 'OV' 'TipoDoc'    , 'Documento' 'Tipo'    from ORDR T100     JOIN RDR1 T0 on T0.DocEntry = T100.DocEntry    where T0.TargetType = -1    and T100.DocDate between @fecha1 and @fecha2    and T100.DocDate >= '20130101'    and T100.DocEntry not in (select BaseEntry from DRF1 where BaseEntry = T100.DocEntry and BaseType = T100.ObjType)        UNION ALL        select distinct       T100.DocNum     , T100.CardName    , T100.TaxDate    , T100.DocDate    , T100.DocDueDate     , 'Facturados' Estado    , 'FV' 'TipoDoc'    , 'Documento' 'Tipo'    from OINV T100     JOIN INV1 T0 on T0.DocEntry = T100.DocEntry    where 1 = 1    and T100.DocDate between @fecha1 and @fecha2    and T100.DocDate >= '20130101'    and T100.DocSubType = '--'            UNION ALL        select distinct T0.DocEntry    , T0.CardName    , T0.TaxDate    , T0.DocDate    , T0.DocDueDate     , CASE when T0.U_Estado_Aut in ('P', 'R') and T0.ObjType = 13 and T1.BaseEntry in (select T0.DocEntry from ORDR T0 JOIN RDR1 T1 on T0.DocEntry = T1.DocEntry where T0.CANCELED = 'Y') Then 'Pedidos Cancelados'          when T0.U_Estado_Aut = 'P' Then 'Pendientes de Autorización'          when T0.U_Estado_Aut = 'R' Then 'Autorización Rechazada' End 'Estado'    , case T0.Objtype when 17 Then 'OV'            else 'FV' End 'TipoDoc'     , 'Borrador' 'Tipo'    from ODRF T0    JOIN DRF1 T1 on T0.docentry = T1.docentry    where T0.ObjType in (17, 13)    and U_Estado_Aut in ('P', 'R')    and T0.DocDate between @fecha1 and @fecha2    and T0.DocDate >= '20160801'        UNION ALL         select distinct T0.DocEntry    , T0.CardName    , T0.TaxDate    , T0.DocDate    , T0.DocDueDate     , CASE T0.U_Estado_Aut when 'A' Then 'Autorizados No Creados'     end 'Estado'    , 'OV' 'TipoDoc'    , 'Borrador' 'Tipo'     from ODRF T0    JOIN DRF1 T1 on T0.docentry = T1.docentry    where T0.ObjType in (17)    and T0.DocDate >= '20160801'    and T0.U_Estado_Aut = 'A'    and (select count(*) from ORDR where draftkey = T0.DocEntry) = 0     and T0.DocDate between @fecha1 and @fecha2        UNION ALL         select distinct T0.DocEntry    , T0.CardName    , T0.TaxDate    , T0.DocDate    , T0.DocDueDate     , CASE when T0.U_Estado_Aut in ('A', 'N') and (select CANCELED from ORDR where DocEntry = T1.baseentry) = 'N' Then 'Autorizados No Creados'          when (select CANCELED from ORDR where DocEntry = T1.baseentry) = 'Y' Then 'Pedidos Cancelados'       end 'Estado'    , 'FV' 'TipoDoc'    , 'Borrador' 'Tipo'     from ODRF T0    JOIN DRF1 T1 on T0.docentry = T1.docentry    where T0.ObjType in (13)    and T0.DocDate >= '20160801'    and T0.U_Estado_Aut in ('A', 'N')    and (select count(*) from OINV where draftkey = T0.DocEntry) = 0    and T0.DocDate between @fecha1 and @fecha2    order by DocDate desc    ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------  end       return  END
  CREATE VIEW [dbo].[TAI_VW_comision_detalle]  AS  SELECT     CodOficina, Oficina, TD, Serie, Año, Mes, Dia, Fecha, NDocSAP, Ind, Folio, Titular, CodOperador, Operador, CodSN, NombreSN, Grupo, CodLinea, Linea, SubLinea,                         Producto, Descripción, Cantidad, Costo, [Costo Total], WhsCode, UnidadMedida, PVUnitNeto, ImpteNetoML, Comision, Envase, KgLt, Capacidad, CodigoProv,                         NombreProveedor, Creacion, CuartaCopia, [Comis%], [Comis%Est], Margen, PrctMargenMin, PrctComisVtas, PrctComisEsp, BaseComis, PrctBajoMargen,                         TopeComision, PorcFlete, PrctComiOpEsp, PrctComision, VtaMarCompartida, VtaCodOperador, VtaNomOperador, Descrip  FROM         TAI_VW_COMISION  /*  UNION  SELECT     CodOficina, Oficina, TD, Serie, Año, Mes, Dia, Fecha, NDocSAP, Ind, Folio, Titular, VtaCodOperador AS CodOperador, VtaNomOperador AS Operador, CodSN,                         NombreSN, Grupo, CodLinea, Linea, SubLinea, Producto, Descripción, Cantidad, Costo, [Costo Total], WhsCode, UnidadMedida, PVUnitNeto, ImpteNetoML, Comision,                         Envase, KgLt, Capacidad, CodigoProv, NombreProveedor, Creacion, CuartaCopia, [Comis%], PrctComision AS [Comis%Est], Margen, PrctMargenMin, PrctComisVtas,                         PrctComisEsp, BaseComis, PrctBajoMargen, TopeComision, PorcFlete, PrctComiOpEsp, PrctComision, 2 VtaMarCompartida, VtaCodOperador, VtaNomOperador,                         Descrip  FROM         TAI_VW_COMISION  WHERE     VtaMarCompartida = 1  UNION  SELECT     CodOficina, Oficina, TD, Serie, Año, Mes, Dia, Fecha, NDocSAP, Ind, Folio, Titular, 236 AS CodOperador, 'Gamerre Araya, Maurice' AS Operador, CodSN, NombreSN,                         Grupo, CodLinea, Linea, SubLinea, Producto, Descripción, Cantidad, Costo, [Costo Total], WhsCode, UnidadMedida, PVUnitNeto, ImpteNetoML, Comision, Envase,                         KgLt, Capacidad, CodigoProv, NombreProveedor, Creacion, CuartaCopia, [Comis%], PrctComision AS [Comis%Est], Margen, PrctMargenMin, PrctComisVtas,                         PrctComisEsp, BaseComis, PrctBajoMargen, TopeComision, PorcFlete, PrctComiOpEsp, PrctComision, 2 VtaMarCompartida, 236 AS VtaCodOperador,                         'Gamerre Araya, Maurice' AS VtaNomOperador, Descrip  FROM         TAI_VW_COMISION  WHERE     CodOficina IN (1, 2, 16, 20) AND CodOperador IN (316, 296, 271) AND CodLinea IN (113, 114, 115, 125, 127, 128, 133)  UNION  SELECT     CodOficina, Oficina, TD, Serie, Año, Mes, Dia, Fecha, NDocSAP, Ind, Folio, Titular, 187 AS CodOperador, 'David Vergara Espinoza' AS Operador, CodSN, NombreSN,                         Grupo, CodLinea, Linea, SubLinea, Producto, Descripción, Cantidad, Costo, [Costo Total], WhsCode, UnidadMedida, PVUnitNeto, ImpteNetoML, Comision, Envase,                         KgLt, Capacidad, CodigoProv, NombreProveedor, Creacion, CuartaCopia, [Comis%], PrctComision AS [Comis%Est], Margen, PrctMargenMin, PrctComisVtas,                         PrctComisEsp, BaseComis, PrctBajoMargen, TopeComision, PorcFlete, PrctComiOpEsp, PrctComision, 2 VtaMarCompartida, 187 AS VtaCodOperador,                         'David Vergara Espinoza' AS VtaNomOperador, Descrip  FROM         TAI_VW_COMISION  WHERE     CodOficina IN (4, 5) AND CodOperador IN (247, 278, 291, 321, 143, 302, 305, 315, 12, 15, 19, 69, 149) AND CodLinea IN (113, 114, 115, 125, 127, 128, 133)  UNION  SELECT     CodOficina, Oficina, TD, Serie, Año, Mes, Dia, Fecha, NDocSAP, Ind, Folio, Titular, 343 AS CodOperador, 'Pino Araya, Jose' AS Operador, CodSN, NombreSN, Grupo,                         CodLinea, Linea, SubLinea, Producto, Descripción, Cantidad, Costo, [Costo Total], WhsCode, UnidadMedida, PVUnitNeto, ImpteNetoML, Comision, Envase, KgLt,                         Capacidad, CodigoProv, NombreProveedor, Creacion, CuartaCopia, [Comis%], PrctComision AS [Comis%Est], Margen, PrctMargenMin, PrctComisVtas, PrctComisEsp,                         BaseComis, PrctBajoMargen, TopeComision, PorcFlete, PrctComiOpEsp, PrctComision, 2 VtaMarCompartida, 343 AS VtaCodOperador,                         'Pino Araya, Jose' AS VtaNomOperador, Descrip  FROM         TAI_VW_COMISION  WHERE     CodOficina IN (6) AND CodOperador IN (63, 239, 281) AND CodLinea IN (113, 114, 115, 125, 127, 128, 133)  UNION  SELECT     CodOficina, Oficina, TD, Serie, Año, Mes, Dia, Fecha, NDocSAP, Ind, Folio, Titular, 146 AS CodOperador, 'Garces Salas, Juan Carlos' AS Operador, CodSN, NombreSN,                         Grupo, CodLinea, Linea, SubLinea, Producto, Descripción, Cantidad, Costo, [Costo Total], WhsCode, UnidadMedida, PVUnitNeto, ImpteNetoML, Comision, Envase,                         KgLt, Capacidad, CodigoProv, NombreProveedor, Creacion, CuartaCopia, [Comis%], PrctComision AS [Comis%Est], Margen, PrctMargenMin, PrctComisVtas,                         PrctComisEsp, BaseComis, PrctBajoMargen, TopeComision, PorcFlete, PrctComiOpEsp, PrctComision, 2 VtaMarCompartida, 146 AS VtaCodOperador,                         'Garces Salas, Juan Carlos' AS VtaNomOperador, Descrip  FROM         TAI_VW_COMISION  WHERE     CodOficina IN (7) AND CodOperador IN (32) AND CodLinea IN (113, 114, 115, 125, 127, 128, 133)  UNION  SELECT     CodOficina, Oficina, TD, Serie, Año, Mes, Dia, Fecha, NDocSAP, Ind, Folio, Titular, 330 AS CodOperador, 'Arancibia Cortes, Williams' AS Operador, CodSN, NombreSN,                         Grupo, CodLinea, Linea, SubLinea, Producto, Descripción, Cantidad, Costo, [Costo Total], WhsCode, UnidadMedida, PVUnitNeto, ImpteNetoML, Comision, Envase,                         KgLt, Capacidad, CodigoProv, NombreProveedor, Creacion, CuartaCopia, [Comis%], PrctComision AS [Comis%Est], Margen, PrctMargenMin, PrctComisVtas,                         PrctComisEsp, BaseComis, PrctBajoMargen, TopeComision, PorcFlete, PrctComiOpEsp, PrctComision, 2 VtaMarCompartida, 330 AS VtaCodOperador,                         'Arancibia Cortes, Williams' AS VtaNomOperador, Descrip  FROM         TAI_VW_COMISION  WHERE     CodOficina IN (3) AND CodOperador IN (277, 313, 342) AND CodLinea IN (113, 114, 115, 125, 127, 128, 133)  UNION  SELECT     CodOficina, Oficina, TD, Serie, Año, Mes, Dia, Fecha, NDocSAP, Ind, Folio, Titular, 188 AS CodOperador, 'Tiznado Silva, Rodrigo  Fernando' AS Operador, CodSN,                         NombreSN, Grupo, CodLinea, Linea, SubLinea, Producto, Descripción, Cantidad, Costo, [Costo Total], WhsCode, UnidadMedida, PVUnitNeto, ImpteNetoML, Comision,                         Envase, KgLt, Capacidad, CodigoProv, NombreProveedor, Creacion, CuartaCopia, [Comis%], PrctComision AS [Comis%Est], Margen, PrctMargenMin, PrctComisVtas,                         PrctComisEsp, BaseComis, PrctBajoMargen, TopeComision, PorcFlete, PrctComiOpEsp, PrctComision, 2 VtaMarCompartida, 188 AS VtaCodOperador,                         'Tiznado Silva, Rodrigo  Fernando' AS VtaNomOperador, Descrip  FROM         TAI_VW_COMISION  WHERE     CodOficina IN (11) AND CodOperador IN (49, 286, 293, 294, 338, 340) AND CodLinea IN (113, 114, 115, 125, 127, 128, 133)  UNION  SELECT     CodOficina, Oficina, TD, Serie, Año, Mes, Dia, Fecha, NDocSAP, Ind, Folio, Titular, 223 AS CodOperador, 'Dittus Baeza, Alvaro' AS Operador, CodSN, NombreSN, Grupo,                         CodLinea, Linea, SubLinea, Producto, Descripción, Cantidad, Costo, [Costo Total], WhsCode, UnidadMedida, PVUnitNeto, ImpteNetoML, Comision, Envase, KgLt,                         Capacidad, CodigoProv, NombreProveedor, Creacion, CuartaCopia, [Comis%], PrctComision AS [Comis%Est], Margen, PrctMargenMin, PrctComisVtas, PrctComisEsp,                         BaseComis, PrctBajoMargen, TopeComision, PorcFlete, PrctComiOpEsp, PrctComision, 2 VtaMarCompartida, 223 AS VtaCodOperador,                         'Dittus Baeza, Alvaro' AS VtaNomOperador, Descrip  FROM         TAI_VW_COMISION  WHERE     CodOficina IN (10) AND CodOperador IN (300, 323, 324, 328, 344) AND CodLinea IN (113, 114, 115, 125, 127, 128, 133)  */  UNION  SELECT     CodOficina, Oficina, TD, Serie, Año, Mes, Dia, Fecha, NDocSAP, Ind, Folio, Titular, VtaCodOperador AS CodOperador, VtaNomOperador AS Operador, CodSN,                         NombreSN, Grupo, CodLinea, Linea, SubLinea, Producto, Descripción, Cantidad, Costo, [Costo Total], WhsCode, UnidadMedida, PVUnitNeto, ImpteNetoML, Comision,                         Envase, KgLt, Capacidad, CodigoProv, NombreProveedor, Creacion, CuartaCopia, [Comis%],                            (SELECT     u_tai_porgrupal                              FROM          [@TAI_PPLINSUC]                              WHERE      Code = CodLinea AND u_succodigo = CodOficina AND u_tai_slpcode = VtaCodOperador) AS [Comis%Est], Margen, PrctMargenMin, PrctComisVtas,                         PrctComisEsp, BaseComis, PrctBajoMargen, TopeComision, PorcFlete, PrctComiOpEsp,                            (SELECT     u_tai_porgrupal                              FROM          [@TAI_PPLINSUC]                              WHERE      Code = CodLinea AND u_succodigo = CodOficina AND u_tai_slpcode = VtaCodOperador) AS PrctComision, 2 VtaMarCompartida, VtaCodOperador,                         VtaNomOperador, Descrip  FROM         TAI_VW_COMISION  WHERE     VtaMarCompartida = 1    
  CREATE VIEW [dbo].[TAI_VW_CtaCte_Cliente]  AS  SELECT     T0.ShortName[CardCode], T2.CardName[CardName], ISNULL(UPPER(T2.MailCity), '') [ShipCity], T2.LicTradNum[LicTradNum], T2.CardType[CardType],                         T0.TransId[TransId], T0.Line_Id[LineId], T0.TransType[TransType],                         CASE T0.TransType WHEN '13' THEN D0.TipoDoc WHEN '14' THEN D0.TipoDoc WHEN '18' THEN D0.TipoDoc WHEN '19' THEN D0.TipoDoc WHEN '203' THEN D0.TipoDoc                         WHEN '204' THEN D0.TipoDoc WHEN '24' THEN D0.TipoDoc WHEN '30' THEN CASE ISNULL(T0.U_VK_TipoDoc, '')                         WHEN '' THEN 'ACM' ELSE T0.U_VK_TipoDoc END WHEN '46' THEN 'PE' WHEN '57' THEN 'CHQ' ELSE 'OTR' END [TipoDoc], CASE ISNULL(T3.FolioPref, '')                         WHEN '' THEN ISNULL(D0.FolioPref, '') ELSE T3.FolioPref END [FolioPref], CASE ISNULL(T3.FolioNum, 0)                         WHEN 0 THEN CASE T0.TransType WHEN '30' THEN CASE WHEN (T0.U_VK_TipoDoc IS NOT NULL) AND (T0.Ref1 IS NOT NULL)                         THEN T0.Ref1 ELSE '' END ELSE ISNULL(LTRIM(STR(D0.FolioNum, 12, 0)), '') END ELSE LTRIM(STR(T3.FolioNum, 12, 0)) END [FolioNum], T0.CreatedBy[DocEntry],                         CAST(T0.BaseRef AS Int) [DocNum], T0.RefDate[DocDate], T0.TaxDate[TaxDate], T0.DueDate[DueDate], DATEDIFF(DAY, T0.DueDate, GETDATE()) [DueDays],                         ISNULL(T0.FCCurrency, '') [FCCurrency], T0.FCDebit[FCDebit], T0.FCCredit[FCCredit], T0.Debit[Debit], T0.Credit[Credit], T0.Debit - T0.Credit[DocTotal],                         CASE T0.TransType WHEN '13' THEN ISNULL                            ((SELECT     ROUND(SUM(Linetotal + Vatsum), 0) * - 1                                FROM         RIN1                                WHERE     BaseType = T0.TransType AND BaseEntry = T0.CreatedBy), 0) WHEN '18' THEN ISNULL                            ((SELECT     ROUND(SUM(Linetotal + Vatsum), 0)                                FROM         RPC1                                WHERE     BaseType = T0.TransType AND BaseEntry = T0.CreatedBy), 0) ELSE 0 END [CrdNoteApplied], CASE T0.TransType WHEN '13' THEN ISNULL                            ((SELECT     SUM(X2.SumApplied) * - 1                                FROM         ORCT X0 JOIN                                                      RCT2 X2 ON X0.DocNum = X2.DocNum                                WHERE     X0.Canceled = 'N' AND X2.InvType = T0.TransType AND X2.DocEntry = T0.CreatedBy), 0) WHEN '18' THEN ISNULL                            ((SELECT     SUM(X2.SumApplied)                                FROM         OVPM X0 JOIN                                                      VPM2 X2 ON X0.DocNum = X2.DocNum                                WHERE     X0.Canceled = 'N' AND X2.InvType = T0.TransType AND X2.DocEntry = T0.CreatedBy), 0) ELSE 0 END [PymntApplied],                         CASE WHEN T0.Debit <> 0 THEN T0.Debit ELSE T0.Credit - T0.BalDueCred END [DebitAppl],                         CASE WHEN T0.Credit <> 0 THEN T0.Credit ELSE T0.Debit - T0.BalDueDeb END [CreditAppl], (T0.BalDueDeb - T0.BalDueCred) [Balance],                         CASE T0.TransType WHEN '13' THEN ISNULL(D0.ReceiptNum, 0) WHEN '14' THEN ISNULL(D0.ReceiptNum, 0) WHEN '18' THEN ISNULL(D0.ReceiptNum, 0)                         WHEN '19' THEN ISNULL(D0.ReceiptNum, 0) WHEN '203' THEN ISNULL(D0.ReceiptNum, 0) WHEN '204' THEN ISNULL(D0.ReceiptNum, 0)                         WHEN '24' THEN CAST(T0.BaseRef AS Int) WHEN '46' THEN CAST(T0.BaseRef AS Int) ELSE 0 END [PymntNum], T0.MthDate[MthDate], T1.FormatCode[FormatCode],                         T1.AcctName[AcctName], T0.LineMemo[LineMemo], ISNULL(T0.Ref1, '') [Ref1], ISNULL(T0.Ref2, '') [Ref2], ISNULL(T0.Ref3Line, '') [Ref3], T1.AcctCode[AcctCode],                         T1.LocManTran[LocManTran], T0.Project[Project], D0.SlpCode[SlpCode], D0.SlpName[SlpName], D0.PymTermCod[DocPayTermC], D0.PymTermNam[DocPayTermN],                         CP.PymntGroup[StdPayTermN], T2.Address[BillAddr], T2.County[BillCounty], T2.City[BillCity], T2.Country[Country], T2.CntctPrsn[CntctPrsn],                         D0.Comments[DocComments], '' [BankCode], '' [BankName], cast((T0.BalDueDeb - T0.BalDueCred) AS numeric(18, 0)) AS balance1  FROM         JDT1 T0 JOIN                        OACT T1 ON T0.Account = T1.AcctCode JOIN                        OCRD T2 ON T0.ShortName = T2.CardCode JOIN                        OCTG CP ON T2.GroupNum = CP.GroupNum JOIN                        OJDT T3 ON T0.TransId = T3.TransId LEFT JOIN                        VK_VW_ODOC D0 ON T0.TransType = D0.ObjType AND T0.CreatedBy = D0.DocEntry  WHERE     1 = 1 AND T0.Account <> T0.ShortName AND (T0.BalDueDeb - T0.BalDueCred) <> 0  UNION ALL  SELECT     T2.CardCode[CardCode], T2.CardName[CardName], '' [ShipCity], T2.LicTradNum[LicTradNum], 'C' [CardType], T3.TransId[TransId], T3.Line_Id[LineId], '24' [TransType],                         'CH' [TipoDoc], '' [FolioPref], LTRIM(STR(CheckNum, 12, 0)) [FolioNum], T0.RcptNum[DocEntry], T0.RcptNum[DocNum], T0.RcptDate[DocDate], T0.CheckDate[TaxDate],                         T0.CheckDate[DueDate], DATEDIFF(DAY, T0.CheckDate, GETDATE()) [DueDays], ISNULL(T3.FCCurrency, '') [FCCurrency], T3.FCDebit[FCDebit], T3.FCCredit[FCCredit],                         T3.Debit[Debit], T3.Credit[Credit], T3.Debit - T3.Credit[DocTotal], 0 [CrdNoteApplied], 0 [PymntApplied],                         CASE WHEN T3.Debit <> 0 THEN T3.Debit ELSE T3.Credit - T3.BalDueCred END [DebitAppl],                         CASE WHEN T3.Credit <> 0 THEN T3.Credit ELSE T3.Debit - T3.BalDueDeb END [CreditAppl], CASE ISNULL(T0.DpstAbs, 0)                         WHEN 0 THEN T3.Debit ELSE 0 END [Balance], T0.RcptNum[PymntNum], T3.MthDate[MthDate], T1.FormatCode[FormatCode], T1.AcctName[AcctName],                         T3.LineMemo[LineMemo], ISNULL(T3.Ref1, '') [Ref1], ISNULL(T3.Ref2, '') [Ref2], ISNULL(T3.Ref3Line, '') [Ref3], T1.AcctCode[AcctCode], T1.LocManTran[LocManTran],                         T3.Project[Project], T2.SlpCode[SlpCode], V0.SlpName[SlpName], NULL [DocPayTermC], NULL [DocPayTermN], CP.PymntGroup[StdPayTermN], T2.Address[BillAddr],                         T2.County[BillCounty], T2.City[BillCity], T2.Country[Country], T2.CntctPrsn[CntctPrsn], '' [DocComments], T0.BankCode[BankCode], BN.BankName[BankName],                         cast((CASE ISNULL(T0.DpstAbs, 0) WHEN 0 THEN T3.Debit ELSE 0 END) AS numeric(18, 0)) AS balance1  FROM         OCHH T0 JOIN                        OACT T1 ON T0.CashCheck = T1.AcctCode JOIN                        OCRD T2 ON T0.CardCode = T2.CardCode JOIN                        OCTG CP ON T2.GroupNum = CP.GroupNum JOIN                        OSLP V0 ON T2.SlpCode = V0.SlpCode JOIN                        JDT1 T3 ON T3.TransType = '24' AND T0.RcptNum = T3.CreatedBy AND T0.RcptLineId = T3.SourceLine AND T3.Account = T3.ShortName LEFT JOIN                        ODSC BN ON T0.BankCode = BN.BankCode  WHERE     1 = 1 AND T0.Canceled = 'N' AND (CASE ISNULL(T0.DpstAbs, 0) WHEN 0 THEN T3.Debit ELSE 0 END) <> 0    
  CREATE VIEW [dbo].[TAI_VW_ValorDespacho]   AS  select FldValue 'ID'  , Descr 'Descripcion'  from UFD1 where TableID = 'ORDR' and FieldID = '45'      